import{_ as n,C as s,o as t,c as r,j as i,E as o,a as e,a2 as d}from"./chunks/framework.C21TwvGF.js";const z=JSON.parse('{"title":"1-hafta","description":"","frontmatter":{"title":"1-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"10-sinf (UX/UI)","link":"/10-sinf-uxui/"},"n":1,"bob":"I-bob · UX/UI dizaynning zamonaviy konsepsiyasi","lessons":[{"g":1,"title":"1-dars: UX dizaynning strategik roli va biznes maqsadlari bilan uyg‘unlashuvi","lead":"UX dizaynning strategik roli va biznes maqsadlari bilan uyg‘unlashuvi","link":"/10-sinf-uxui/hafta-01/dars-1","slide":"/slaydlar/10-sinf-uxui/hafta-01/dars-1.html","test":"/slaydlar/10-sinf-uxui/hafta-01/dars-1-test.html"},{"g":2,"title":"2-dars: Foydalanuvchiga yo‘naltirilgan dizayn (User-Centered Design — UCD) tamoyillari va bosqichlari","lead":"Foydalanuvchiga yo‘naltirilgan dizayn (User-Centered Design — UCD)","link":"/10-sinf-uxui/hafta-01/dars-2","slide":"/slaydlar/10-sinf-uxui/hafta-01/dars-2.html","test":"/slaydlar/10-sinf-uxui/hafta-01/dars-2-test.html"},{"g":3,"title":"3-dars: Interfeys dizaynida asosiy tamoyillar: Usability, Accessibility, Simplicity","lead":"Interfeys dizaynida asosiy tamoyillar: usability, accessibility, simplicity","link":"/10-sinf-uxui/hafta-01/dars-3","slide":"/slaydlar/10-sinf-uxui/hafta-01/dars-3.html","test":"/slaydlar/10-sinf-uxui/hafta-01/dars-3-test.html"}],"test":"/slaydlar/10-sinf-uxui/hafta-01/hafta-test.html"}},"headers":[],"relativePath":"10-sinf-uxui/hafta-01/index.md","filePath":"10-sinf-uxui/hafta-01/index.md"}'),y={name:"10-sinf-uxui/hafta-01/index.md"},h={class:"blk"},u={id:"uyga-vazifa",tabindex:"-1"};function g(m,a,c,b,f,k){const l=s("Icon");return t(),r("div",null,[i("div",h,[i("h2",u,[o(l,{name:"house"}),a[0]||(a[0]=e(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=d('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan.</p><hr><h3 id="_1-dars-ux-dizaynning-strategik-roli-va-biznes-maqsadlari-bilan-uyg-unlashuvi" tabindex="-1">1-dars: UX dizaynning strategik roli va biznes maqsadlari bilan uyg‘unlashuvi <a class="header-anchor" href="#_1-dars-ux-dizaynning-strategik-roli-va-biznes-maqsadlari-bilan-uyg-unlashuvi" aria-label="Permalink to &quot;1-dars: UX dizaynning strategik roli va biznes maqsadlari bilan uyg‘unlashuvi&quot;">​</a></h3><ol><li>Mahalliy elektron do&#39;kon (yoki xizmat ko&#39;rsatish sayti) tanlang va uning bosh sahifasi hamda xarid jarayonini tahlil qiling.</li><li>Saytdagi 2 ta asosiy biznes maqsadi (masalan, konversiyani oshirish, savatni tark etishni kamaytirish)ni aniqlang.</li><li>Foydalanuvchilar xarid jarayonida duch kelishi mumkin bo&#39;lgan 2 ta og&#39;riqli nuqtani (pain point) yozing va ularga mos UX yechim taklif qiling.</li><li>Agar oyiga saytga 15 000 kishi tashrif buyursa va shulardan 450 nafari xarid qilsa, dastlabki konversiya foizini toping. Qulay UX evaziga xaridorlar 900 nafarga yetsa, konversiya necha foizga oshishini hisoblang.</li></ol><hr><h3 id="_2-dars-foydalanuvchiga-yo-naltirilgan-dizayn-user-centered-design-—-ucd-tamoyillari-va-bosqichlari" tabindex="-1">2-dars: Foydalanuvchiga yo‘naltirilgan dizayn (User-Centered Design — UCD) tamoyillari va bosqichlari <a class="header-anchor" href="#_2-dars-foydalanuvchiga-yo-naltirilgan-dizayn-user-centered-design-—-ucd-tamoyillari-va-bosqichlari" aria-label="Permalink to &quot;2-dars: Foydalanuvchiga yo‘naltirilgan dizayn (User-Centered Design — UCD) tamoyillari va bosqichlari&quot;">​</a></h3><ol><li>UCD ning 10 ta tamoyilidan kamida 3 tasini (masalan, Moslik, Qayta aloqa va Xatolarning oldini olish) o&#39;zingiz faol ishlatadigan mobil ilova (Telegram, Click, Uzum va h.k.) misolida tasvirlab bering.</li><li>Tizimdagi xatolik xabarlarini tahlil qiling: nima uchun &quot;Error 404&quot; yoki texnik kodlar o&#39;rniga samimiy va yechim ko&#39;rsatuvchi matn yozish zarurligini tushuntiring.</li><li>4 bosqichli UCD sikli (Kontekst -&gt; Talablar -&gt; Yechim -&gt; Baholash) bo&#39;yicha kichik xizmat (masalan, maktab oshxonasiga navbatsiz tushlik buyurtma qilish ilovasi) uchun har bir bosqichda nima ish qilinishini 1-2 jumlada bayon qiling.</li></ol><hr><h3 id="_3-dars-interfeys-dizaynida-asosiy-tamoyillar-usability-accessibility-simplicity" tabindex="-1">3-dars: Interfeys dizaynida asosiy tamoyillar: Usability, Accessibility, Simplicity <a class="header-anchor" href="#_3-dars-interfeys-dizaynida-asosiy-tamoyillar-usability-accessibility-simplicity" aria-label="Permalink to &quot;3-dars: Interfeys dizaynida asosiy tamoyillar: Usability, Accessibility, Simplicity&quot;">​</a></h3><ol><li>Usability, Accessibility va Simplicity tamoyillarining o&#39;zaro farqini va bir-birini qanday to&#39;ldirishini yozing.</li><li>WCAG rang kontrasti talabiga ko&#39;ra nega matn va fon kontrasti kamida 4.5:1 bo&#39;lishi kerakligini hayotiy misol bilan tushuntiring.</li><li>Hick qonuniga binoan ekrandagi tanlovlar soni ko&#39;payganda foydalanuvchida qanday muammo yuzaga kelishini ko&#39;rsating va uni soddalashtirish uchun 1 ta amaliy yechim bering.</li><li>Amazon&#39;ning &quot;1-Click&quot; yoki Airbnb&#39;ning inkluzivlik filtrlaridan birini tanlab, ushbu yechim qaysi tamoyilga mos kelishini tahlil qiling.</li></ol><hr>',11))])])}const q=n(y,[["render",g]]);export{z as __pageData,q as default};
